def L(domain_id, title, concepts, code, walkthrough, pitfalls, try_it):
    return {"title": title, "domain_id": domain_id, "concepts": concepts,
            "example": {"code": code, "walkthrough": walkthrough},
            "pitfalls": pitfalls, "try_it": try_it}

def S(sid, domain_id, title, situation, objectives, evidence, prompt, choices, answer, hint, why, mins):
    return {"id": sid, "title": title, "domain_id": domain_id, "situation": situation,
            "objectives": objectives, "evidence": evidence, "prompt": prompt,
            "choices": choices, "answer": answer, "hint": hint, "why": why, "mins": mins}

def B(lid, title, objective, steps, checks, success):
    return {"id": lid, "title": title, "objective": objective,
            "steps": steps,
            "checks": [{"command_pattern": p, "expect_contains": e, "hint": h} for (p, e, h) in checks],
            "success_message": success}

